const float h_cubed = h_squared * h;
const float h_nine = h_cubed * h * h * h * h * h; // h^9

// Poly6 kernel at zero distance: W(r=0) = (315 / (64πh^9))
const float poly6_zero = (315.0f / (64.0f * PI * h_nine)) * poly6;

return mass * poly6_zero;

